#pragma warning disable IDE0130
#pragma warning disable IDE0290

using Barotrauma;
using Microsoft.Xna.Framework;

namespace SOS.GUI
{
    /// <summary>
    /// Flags controlling which system buttons are displayed in the window header.
    /// </summary>
    /// <remarks>
    /// Use bitwise OR to combine flags (e.g., <c>WindowButtons.Minimize | WindowButtons.Close</c>).
    /// Default is <see cref="All"/>.
    /// </remarks>
    [Flags]
    public enum WindowButtons
    {
        /// <summary>No system buttons.</summary>
        None = 0,
        /// <summary>Show minimize button.</summary>
        Minimize = 1 << 0,
        /// <summary>Show maximize/restore button.</summary>
        Maximize = 1 << 1,
        /// <summary>Show close button.</summary>
        Close = 1 << 2,
        /// <summary>Show minimize and close buttons.</summary>
        MinClose = Minimize | Close,
        /// <summary>Show maximize and close buttons.</summary>
        MaxClose = Maximize | Close,
        /// <summary>Show all system buttons (default).</summary>
        All = Minimize | Maximize | Close
    }

    /// <summary>
    /// Standardized resizable window with a fixed top bar (toolbox, title, custom and system buttons)
    /// and a content area that fills the remaining vertical space.
    /// </summary>
    /// <remarks>
    /// Inherits from <see cref="GUIResizableFrame"/> providing drag-to-move and edge-resize functionality.
    /// The window consists of:
    /// <list type="bullet">
    /// <item><term>TopBar:</term><description>Fixed-height header containing title, toolbox, and system buttons.</description></item>
    /// <item><term>ToolBox:</term><description>Left area for custom controls (32% width).</description></item>
    /// <item><term>ControlBox:</term><description>Right area for custom controls (60% of right area).</description></item>
    /// <item><term>SystemBox:</term><description>Rightmost area for system buttons (minimize, maximize, close).</description></item>
    /// <item><term>ContentArea:</term><description>Fill-area below the header for window content.</description></item>
    /// </list>
    /// <para>
    /// System buttons (minimize, maximize, close) are created based on the <see cref="WindowButtons"/> flags.
    /// The window supports two modes: <see cref="WindowMode.Windowed"/> (default) and <see cref="WindowMode.Fullscreen"/>.
    /// In fullscreen mode, the window fills its parent rect and resizing is disabled.
    /// </para>
    /// </remarks>
    /// <example>
    /// <code>
    /// var window = new GUIWindow(
    ///     new RectTransform(new Point(600, 400), GUI.Canvas, Anchor.Center),
    ///     "My Window Title",
    ///     style: "InnerFrame",
    ///     buttons: WindowButtons.All,
    ///     mode: WindowMode.Windowed);
    ///
    /// window.ToolBox.AddChild(new GUIButton(...));
    /// window.ContentArea.AddChild(new GUIListBox(...));
    /// window.Open();
    /// </code>
    /// </example>
    public class GUIWindow : GUIResizableFrame
    {
        /// <summary>
        /// Default header height in pixels.
        /// </summary>
        public const int DefaultHeaderHeight = 42;

        private const int SystemButtonSize = 32;

        /// <summary>
        /// The top header bar frame.
        /// </summary>
        public readonly GUIFrame TopBar;

        /// <summary>
        /// The title text block in the header.
        /// </summary>
        public readonly GUITextBlock Title;

        /// <summary>
        /// Left toolbox area for custom controls (32% of header width).
        /// </summary>
        public readonly GUILayoutGroup ToolBox;

        /// <summary>
        /// Right area containing ControlBox and SystemBox.
        /// </summary>
        public readonly GUILayoutGroup RightArea;

        /// <summary>
        /// Custom controls area (60% of right area width).
        /// </summary>
        public readonly GUILayoutGroup ControlBox;

        /// <summary>
        /// System buttons area (minimize, maximize, close).
        /// </summary>
        public readonly GUILayoutGroup SystemBox;

        /// <summary>
        /// Main content area below the header.
        /// </summary>
        public readonly GUIFrame ContentArea;

        /// <summary>
        /// The minimize button, or <c>null</c> if <see cref="WindowButtons.Minimize"/> not specified.
        /// </summary>
        public readonly GUIButton? MinimizeButton;

        /// <summary>
        /// The maximize/restore button, or <c>null</c> if <see cref="WindowButtons.Maximize"/> not specified.
        /// </summary>
        public readonly GUIButton? MaximizeButton;

        /// <summary>
        /// The close button, or <c>null</c> if <see cref="WindowButtons.Close"/> not specified.
        /// </summary>
        public readonly GUIButton? CloseButton;

        /// <summary>
        /// The window's size in windowed mode (persisted across maximize/restore).
        /// </summary>
        public Point NormalSize { get; protected set; }

        /// <summary>
        /// The window's position offset in windowed mode (persisted across maximize/restore).
        /// </summary>
        public Point NormalOffset { get; protected set; }

        /// <summary>
        /// Event invoked when the window is minimized.
        /// </summary>
        public event Action? OnMinimize;

        /// <summary>
        /// Event invoked when the window is maximized.
        /// </summary>
        public event Action? OnMaximize;

        /// <summary>
        /// Event invoked when the window is restored from maximized to windowed.
        /// </summary>
        public event Action? OnRestore;

        /// <summary>
        /// Event invoked when the window is closed.
        /// </summary>
        public event Action? OnClose;

        private WindowMode _mode = WindowMode.Windowed;
        private ResizeDirection _normalResizeDirections = ResizeDirection.All;

        /// <summary>
        /// Gets whether the window can be moved by dragging.
        /// </summary>
        /// <returns><c>true</c> in windowed mode; <c>false</c> in fullscreen.</returns>
        public override bool CanMove => Mode != WindowMode.Fullscreen;

        /// <summary>
        /// Gets or sets the window display mode.
        /// </summary>
        /// <remarks>
        /// Setting this property invokes <see cref="SetMode"/> which handles the transition
        /// between windowed and fullscreen, including UI updates and event invocation.
        /// </remarks>
        public WindowMode Mode
        {
            get => _mode;
            set => SetMode(value);
        }

        /// <summary>
        /// Creates a new standardized window.
        /// </summary>
        /// <param name="rectT">The rectangle transform defining initial position and size.</param>
        /// <param name="titleText">The window title text.</param>
        /// <param name="style">GUI style name. Defaults to "InnerFrame".</param>
        /// <param name="color">Optional background color.</param>
        /// <param name="buttons">System buttons to display. Defaults to <see cref="WindowButtons.All"/>.</param>
        /// <param name="mode">Initial window mode. Defaults to <see cref="WindowMode.Windowed"/>.</param>
        /// <remarks>
        /// The constructor builds the complete window structure:
        /// <list type="number">
        /// <item>TopBar with fixed height <see cref="DefaultHeaderHeight"/>.</item>
        /// <item>Title centered in TopBar.</item>
        /// <item>ToolBox (left, 32%) and RightArea (right, 20%) with ControlBox (60%) and SystemBox (40%).</item>
        /// <item>System buttons based on <paramref name="buttons"/> flags.</item>
        /// <item>ContentArea below header, auto-sized on resize.</item>
        /// </list>
        /// </remarks>
        public GUIWindow(RectTransform rectT, LocalizedString titleText, string style = "InnerFrame", Color? color = null, WindowButtons buttons = WindowButtons.All, WindowMode mode = WindowMode.Windowed)
            : base(rectT, style, color)
        {
            CanBeFocused = true;
            AllowedDirections = ResizeDirection.All;
            NormalSize = RectTransform.NonScaledSize;
            NormalOffset = RectTransform.AbsoluteOffset;
            Mode = mode;

            TopBar = new GUIFrame(new RectTransform(new Vector2(1f, 0f), RectTransform, Anchor.TopCenter)
            {
                MinSize = new Point(0, DefaultHeaderHeight),
                MaxSize = new Point(int.MaxValue, DefaultHeaderHeight)
            }, style: "GUIFrameBottom")
            {
                CanBeFocused = false
            };

            Title = new GUITextBlock(new RectTransform(Vector2.One, TopBar.RectTransform), titleText, font: GUIStyle.LargeFont, textAlignment: Alignment.Center)
            {
                CanBeFocused = false,
                Wrap = false
            };

            ToolBox = new GUILayoutGroup(new RectTransform(new Vector2(0.32f, 0.8f), TopBar.RectTransform, Anchor.CenterLeft) { AbsoluteOffset = new Point(10, 0) }, isHorizontal: true)
            {
                Stretch = false,
                AbsoluteSpacing = 5,
                CanBeFocused = false
            };

            RightArea = new GUILayoutGroup(new RectTransform(new Vector2(0.2f, 0.8f), TopBar.RectTransform, Anchor.CenterRight) { AbsoluteOffset = new Point(10, 0) }, isHorizontal: true)
            {
                Stretch = false,
                AbsoluteSpacing = 5,
                ChildAnchor = Anchor.CenterRight,
                CanBeFocused = false
            };

            SystemBox = new GUILayoutGroup(new RectTransform(new Vector2(0.4f, 1f), RightArea.RectTransform), isHorizontal: true, childAnchor: Anchor.CenterRight)
            {
                Stretch = false,
                AbsoluteSpacing = 4,
                CanBeFocused = false
            };

            ControlBox = new GUILayoutGroup(new RectTransform(new Vector2(0.6f, 1f), RightArea.RectTransform), isHorizontal: true, childAnchor: Anchor.CenterRight)
            {
                Stretch = false,
                AbsoluteSpacing = 5,
                CanBeFocused = false
            };

            if (buttons.HasFlag(WindowButtons.Close))
            {
                CloseButton = CreateSystemButton("", "GUICancelButton", Texts.Get("sos.gen.close", "Close [Esc]"), Close);
            }

            if (buttons.HasFlag(WindowButtons.Maximize))
            {
                MaximizeButton = CreateSystemButton("M", "DeviceButton", Texts.Get("sos.window.maximize", "Maximize"), ToggleMaximize);
            }

            if (buttons.HasFlag(WindowButtons.Minimize))
            {
                MinimizeButton = CreateSystemButton("-", "DeviceButton", Texts.Get("sos.window.minimize", "Minimize"), Minimize);
            }

            UpdateSystemBoxSize();

            ContentArea = new GUIFrame(new RectTransform(new Point(0, 0), RectTransform, Anchor.TopLeft, isFixedSize: true)
            {
                AbsoluteOffset = new Point(0, DefaultHeaderHeight)
            }, style: null);

            RectTransform.SizeChanged += ResizeContentArea;
            ResizeContentArea();
        }

        /// <summary>
        /// Creates a system button in the SystemBox.
        /// </summary>
        /// <param name="text">Button text.</param>
        /// <param name="style">Button style name.</param>
        /// <param name="tooltipKey">Localization key for tooltip.</param>
        /// <param name="tooltipFallback">Fallback tooltip text.</param>
        /// <param name="onClick">Click handler.</param>
        /// <returns>The created button, or <c>null</c> on failure.</returns>
        private GUIButton CreateSystemButton(string text, string style, LocalizedString tooltip, Action onClick)
        {
            try
            {
                var button = new GUIButton(new RectTransform(new Point(SystemButtonSize, SystemButtonSize), SystemBox.RectTransform, isFixedSize: true), text, style: style)
                {
                    ToolTip = tooltip,
                    OnClicked = (_, _) =>
                    {
                        try
                        {
                            onClick();
                        }
                        catch (Exception ex)
                        {
                            Logger.LogDebugError($"[SOS] GUIWindow system button action failed\n{ex}", level: LogLevel.Error);
                        }
                        return true;
                    }
                };
                return button;
            }
            catch (Exception ex)
            {
                Logger.LogDebugError($"[SOS] GUIWindow.CreateSystemButton failed\n{ex}", level: LogLevel.Error);
                return null!;
            }
        }

        /// <summary>
        /// Updates the SystemBox width to fit its children.
        /// </summary>
        private void UpdateSystemBoxSize()
        {
            int count = SystemBox.Children.Count();
            if (count == 0) return;

            int width = SystemBox.Children.Sum(c => c.Rect.Width) + SystemBox.AbsoluteSpacing * (count - 1);
            SystemBox.RectTransform.IsFixedSize = true;
            SystemBox.RectTransform.NonScaledSize = new Point(width, SystemBox.Rect.Height);
            RefreshRightAreaSize();
        }

        /// <summary>
        /// Updates the ControlBox width and refreshes the right area layout.
        /// </summary>
        /// <remarks>
        /// Called internally when custom controls are added to <see cref="ControlBox"/>.
        /// </remarks>
        internal void SetControlBoxContentWidth()
        {
            int count = ControlBox.Children.Count();
            if (count == 0) return;

            int width = ControlBox.Children.Sum(c => c.Rect.Width) + ControlBox.AbsoluteSpacing * (count - 1);
            ControlBox.RectTransform.IsFixedSize = true;
            ControlBox.RectTransform.NonScaledSize = new Point(width, ControlBox.Rect.Height);
            RefreshRightAreaSize();
        }

        /// <summary>
        /// Recalculates the RightArea width based on SystemBox and ControlBox sizes.
        /// </summary>
        internal void RefreshRightAreaSize()
        {
            int width = SystemBox.Rect.Width;
            if (ControlBox.Children.Any())
                width += ControlBox.Rect.Width + RightArea.AbsoluteSpacing;

            RightArea.RectTransform.IsFixedSize = true;
            RightArea.RectTransform.NonScaledSize = new Point(width, RightArea.Rect.Height);
        }

        /// <summary>
        /// Shows the window and optionally forces a display mode.
        /// </summary>
        /// <param name="forceMode">Mode to apply when opening. Defaults to <see cref="WindowMode.Windowed"/>.</param>
        public void Open(WindowMode forceMode = WindowMode.Windowed)
        {
            Visible = true;
            Mode = forceMode;
        }

        /// <summary>
        /// Minimizes the window (hides it) and invokes <see cref="OnMinimize"/>.
        /// </summary>
        public void Minimize()
        {
            Visible = false;
            OnMinimize?.Invoke();
        }

        /// <summary>
        /// Maximizes the window to fullscreen.
        /// </summary>
        public void Maximize() => Mode = WindowMode.Fullscreen;

        /// <summary>
        /// Restores the window from fullscreen to windowed mode.
        /// </summary>
        public void Restore() => Mode = WindowMode.Windowed;

        /// <summary>
        /// Toggles between fullscreen and windowed mode.
        /// </summary>
        public void ToggleMaximize() => Mode = Mode == WindowMode.Fullscreen ? WindowMode.Windowed : WindowMode.Fullscreen;

        /// <summary>
        /// Closes the window (hides it) and invokes <see cref="OnClose"/>.
        /// </summary>
        public void Close()
        {
            Visible = false;
            OnClose?.Invoke();
        }

        /// <summary>
        /// Updates the window, preserving normal size/offset in windowed mode.
        /// </summary>
        /// <param name="deltaTime">Time since last update in seconds.</param>
        public override void Update(float deltaTime)
        {
            try
            {
                base.Update(deltaTime);
                if (!Visible || Mode == WindowMode.Fullscreen) return;

                NormalSize = RectTransform.NonScaledSize;
                NormalOffset = RectTransform.AbsoluteOffset;
            }
            catch (Exception ex)
            {
                Logger.LogDebugError($"[SOS] GUIWindow.Update failed\n{ex}", level: LogLevel.Error);
            }
        }

        /// <summary>
        /// Changes the window mode with full transition logic.
        /// </summary>
        /// <param name="newMode">The new mode to apply.</param>
        /// <remarks>
        /// Handles the transition:
        /// <list type="bullet">
        /// <item><term>Fullscreen:</term><description>Saves current size/position, disables resize, fills parent rect.</description></item>
        /// <item><term>Windowed:</term><description>Restores saved size/position, restores resize directions.</description></item>
        /// </list>
        /// Invokes <see cref="OnMaximize"/> or <see cref="OnRestore"/> accordingly.
        /// </remarks>
        private void SetMode(WindowMode newMode)
        {
            if (_mode == newMode) return;

            try
            {
                _mode = newMode;

                switch (_mode)
                {
                    case WindowMode.Fullscreen:
                        EnterMaximized();
                        UpdateSystemButtons();
                        OnMaximize?.Invoke();
                        break;
                    case WindowMode.Windowed:
                        ExitMaximized();
                        UpdateSystemButtons();
                        OnRestore?.Invoke();
                        break;
                }
            }
            catch (Exception ex)
            {
                Logger.LogDebugError($"[SOS] GUIWindow.SetMode failed\n{ex}", level: LogLevel.Error);
            }
        }

        /// <summary>
        /// Transitions to fullscreen mode.
        /// </summary>
        private void EnterMaximized()
        {
            NormalSize = RectTransform.NonScaledSize;
            NormalOffset = RectTransform.AbsoluteOffset;
            _normalResizeDirections = AllowedDirections;

            AllowedDirections = ResizeDirection.None;
            RectTransform.NonScaledSize = RectTransform.ParentRect.Size;
            RectTransform.AbsoluteOffset = Point.Zero;
        }

        /// <summary>
        /// Transitions from fullscreen back to windowed mode.
        /// </summary>
        private void ExitMaximized()
        {
            AllowedDirections = _normalResizeDirections;
            RectTransform.NonScaledSize = NormalSize;
            RectTransform.AbsoluteOffset = NormalOffset;
        }

        /// <summary>
        /// Updates the maximize button text and tooltip based on current mode.
        /// </summary>
        private void UpdateSystemButtons()
        {
            if (MaximizeButton == null) return;

            bool isMaximized = Mode == WindowMode.Fullscreen;
            MaximizeButton.Text = isMaximized ? Texts.Get("sos.window.restore_btn", "R") : Texts.Get("sos.window.maximize_btn", "M");
            MaximizeButton.ToolTip = isMaximized ? Texts.Get("sos.window.restore", "Restore") : Texts.Get("sos.window.maximize", "Maximize");
        }

        /// <summary>
        /// Resizes the ContentArea to fill the window below the header.
        /// </summary>
        private void ResizeContentArea()
        {
            if (ContentArea == null) return;

            try
            {
                int width = RectTransform.Rect.Width;
                int height = Math.Max(0, RectTransform.Rect.Height - DefaultHeaderHeight);
                ContentArea.RectTransform.NonScaledSize = new Point(width, height);
            }
            catch (Exception ex)
            {
                Logger.LogDebugError($"[SOS] GUIWindow.ResizeContentArea failed\n{ex}", level: LogLevel.Error);
            }
        }
    }
}